    else:
        print(f'{epost} är ogiltig')

class Bankkonto:
    """Enkel modell för ett bankkonto."""

    def __init__(self, ägare, saldo=0):
        self.ägare = ägare
        self._saldo = saldo

    def sätt_in(self, belopp):
        if belopp > 0:
            self._saldo += belopp
            return True
        return False

    def ta_ut(self, belopp):
        if 0 < belopp <= self._saldo:
            self._saldo -= belopp
            return True
        return False

    @property
    def saldo(self):
        return self._saldo

    def __str__(self):
        return f'{self.ägare}s konto: {self._saldo} kr'

# Exempel
konto = Bankkonto('Anna', 1000)
konto.sätt_in(500)
print(konto)  # -> Annas konto: 1500 kr

def beräkna_medelvärde(lista):
