def platta_ut(lista):
    """Plattar ut en nästlad lista."""
    resultat = []
    for element in lista:
        if isinstance(element, list):
            resultat.extend(platta_ut(element))
        else:
            resultat.append(element)
    return resultat

# Exempel
nästlad = [1, [2, 3], [4, [5, 6]], 7]
print(platta_ut(nästlad))  # -> [1, 2, 3, 4, 5, 6, 7]

from collections import Counter

def räkna_ordförekomster(text):
    """Räknar hur ofta varje ord förekommer."""
    ord_lista = text.lower().split()
    return dict(Counter(ord_lista))

# Exempel
text = 'Hej hej på dig hur mår du hej'
förekomster = räkna_ordförekomster(text)
print(förekomster)  # -> {'hej': 3, 'på': 1, 'dig': 1, 'hur': 1, 'mår': 1, 'du': 1}

def komprimera_sträng(text):
    """Komprimerar en sträng med run-length encoding."""
    if not text:
        return ''

    resultat = []
    räknare = 1
    föregående = text[0]

    for tecken in text[1:]:
        if tecken == föregående:
            räknare += 1
        else:
            resultat.append(f'{föregående}{räknare}')
            föregående = tecken
            räknare = 1

    resultat.append(f'{föregående}{räknare}')
    return ''.join(resultat)

# Exempel
print(komprimera_sträng('aaabbbcccc'))  # -> a3b3c4

class Nod:
    """En nod i en länkad lista."""
    def __init__(self, data):
        self.data = data
        self.nästa = None

class LänkadLista:
    """En enkel länkad lista."""

    def __init__(self):
        self.huvud = None

    def lägg_till(self, data):
        ny_nod = Nod(data)
        if not self.huvud:
            self.huvud = ny_nod
        else:
            nuvarande = self.huvud
            while nuvarande.nästa:
                nuvarande = nuvarande.nästa
            nuvarande.nästa = ny_nod

    def visa(self):
        element = []
        nuvarande = self.huvud
        while nuvarande:
            element.append(nuvarande.data)
            nuvarande = nuvarande.nästa
        return element

# Exempel
lista = LänkadLista()
lista.lägg_till(1)
lista.lägg_till(2)
lista.lägg_till(3)
print(lista.visa())  # -> [1, 2, 3]

def validera_personnummer(pnr):
    """Validerar ett svenskt personnummer med Luhn-algoritmen."""
    # Ta bort bindestreck
    pnr = pnr.replace('-', '')

    if len(pnr) != 10 and len(pnr) != 12:
        return False

    # Ta de sista 10 siffrorna
    if len(pnr) == 12:
        pnr = pnr[2:]

    # Luhn-algoritmen
    summa = 0
    for i, siffra in enumerate(pnr[:9]):
        tal = int(siffra)
        if i % 2 == 0:
            tal *= 2
            if tal > 9:
                tal -= 9
        summa += tal

    kontrollsiffra = (10 - (summa % 10)) % 10
    return kontrollsiffra == int(pnr[9])

# Exempel
print(validera_personnummer('811228-9874'))

class AttGöraLista:
    """En enkel att-göra-lista."""

    def __init__(self):
        self.uppgifter = []

    def lägg_till(self, uppgift):
        self.uppgifter.append({'text': uppgift, 'klar': False})
        print(f'Lade till: {uppgift}')

    def markera_klar(self, index):
        if 0 <= index < len(self.uppgifter):
            self.uppgifter[index]['klar'] = True
            print(f'Markerade som klar: {self.uppgifter[index]["text"]}')

    def visa(self):
        for i, uppgift in enumerate(self.uppgifter):
            status = '✓' if uppgift['klar'] else '○'
            print(f'{i}. [{status}] {uppgift["text"]}')

# Exempel
