lista.lägg_till('Handla mat')
lista.lägg_till('Träna')
lista.markera_klar(0)
lista.visa()

def största_gemensamma_delare(a, b):
    """Beräknar största gemensamma delare med Euklides algoritm."""
    while b:
        a, b = b, a % b
    return a

# Alternativ med rekursion
def gcd_rekursiv(a, b):
    """Rekursiv version av GCD."""
    if b == 0:
        return a
    return gcd_rekursiv(b, a % b)

# Exempel
print(största_gemensamma_delare(48, 18))  # -> 6

def är_balanserad(text):
    """Kontrollerar om parenteser är balanserade."""
    stack = []
    par = {'(': ')', '[': ']', '{': '}'}

    for tecken in text:
        if tecken in par:
            stack.append(tecken)
        elif tecken in par.values():
            if not stack:
                return False
            if par[stack.pop()] != tecken:
                return False

    return len(stack) == 0

# Exempel
texter = ['((()))', '([{}])', '(()', '{[}]']
for text in texter:
    resultat = 'balanserad' if är_balanserad(text) else 'obalanserad'
    print(f'{text} är {resultat}')

def visa_meny(alternativ):
    """Visar en meny och returnerar användarens val."""
    while True:
        print('\n=== MENY ===')
        for i, alt in enumerate(alternativ, 1):
            print(f'{i}. {alt}')
        print('0. Avsluta')

        try:
            val = int(input('\nVälj ett alternativ: '))
            if val == 0:
                return None
            if 1 <= val <= len(alternativ):
                return alternativ[val - 1]
            print('Ogiltigt val, försök igen.')
        except ValueError:
            print('Ange ett nummer.')

