def potens(bas, exponent):
    """Beräknar potens utan att använda ** operatorn."""
    if exponent == 0:
        return 1
    if exponent < 0:
        return 1 / potens(bas, -exponent)

    resultat = 1
    for _ in range(exponent):
        resultat *= bas
    return resultat

# Rekursiv version
def potens_rekursiv(bas, exponent):
    """Rekursiv version."""
    if exponent == 0:
        return 1
    if exponent < 0:
        return 1 / potens_rekursiv(bas, -exponent)
    return bas * potens_rekursiv(bas, exponent - 1)

# Exempel
print(potens(2, 10))  # -> 1024
print(potens(2, -2))  # -> 0.25

class Kontaktbok:
    """Ett enkelt kontakthanteringssystem."""

    def __init__(self):
        self.kontakter = {}

    def lägg_till(self, namn, telefon, epost=None):
        self.kontakter[namn] = {
            'telefon': telefon,
            'epost': epost
        }
        print(f'Lade till {namn}')

    def sök(self, sökterm):
        resultat = []
        for namn, info in self.kontakter.items():
            if sökterm.lower() in namn.lower():
                resultat.append((namn, info))
        return resultat

    def ta_bort(self, namn):
        if namn in self.kontakter:
            del self.kontakter[namn]
            print(f'Tog bort {namn}')

    def visa_alla(self):
        for namn, info in self.kontakter.items():
            print(f'{namn}: {info["telefon"]}')

# Exempel
bok = Kontaktbok()
bok.lägg_till('Anna Svensson', '070-1234567', 'anna@email.se')
bok.lägg_till('Erik Johansson', '073-7654321')
bok.visa_alla()

def caesar_kryptera(text, steg):
    """Krypterar text med Caesar-chiffer."""
    resultat = []

    for tecken in text:
        if tecken.isalpha():
            ascii_offset = ord('A') if tecken.isupper() else ord('a')
            nytt_tecken = chr((ord(tecken) - ascii_offset + steg) % 26 + ascii_offset)
            resultat.append(nytt_tecken)
        else:
            resultat.append(tecken)

    return ''.join(resultat)

def caesar_dekryptera(text, steg):
    """Dekrypterar text krypterad med Caesar-chiffer."""
    return caesar_kryptera(text, -steg)

# Exempel
original = 'Hej på dig!'
krypterad = caesar_kryptera(original, 3)
dekrypterad = caesar_dekryptera(krypterad, 3)
print(f'Original: {original}')
print(f'Krypterad: {krypterad}')
print(f'Dekrypterad: {dekrypterad}')
